"use client"

import { useState } from "react"
import { motion } from "framer-motion"
import { ChatMessage } from "../lib/socket"

type Props = {
  message: ChatMessage
  currentUser: string
  react: (id: string, emoji: string) => void
  editMessage: (id: string, text: string) => void
  deleteMessage: (id: string) => void
  grouped?: boolean
}

export default function MessageBubble({
  message,
  currentUser,
  react,
  editMessage,
  deleteMessage,
  grouped
}: Props) {

  const [editing, setEditing] = useState(false)
  const [editText, setEditText] = useState(message.message)
  const [showBar, setShowBar] = useState(false)

  const isMe = message.username === currentUser

  const time = message.createdAt
    ? new Date(message.createdAt).toLocaleTimeString("en-IN", {
        hour: "2-digit",
        minute: "2-digit"
      })
    : ""

  const avatar = message.username?.charAt(0).toUpperCase()

  const file = message.message || ""
  const ext = file.split(".").pop()?.toLowerCase()

  const isImage = ["jpg","jpeg","png","gif","webp"].includes(ext || "")
  const isVideo = ["mp4","webm","mov"].includes(ext || "")
  const isAudio = ["mp3","wav","ogg","webm"].includes(ext || "")
  const isDoc = ["pdf","doc","docx","ppt","pptx","xls","xlsx","txt"].includes(ext || "")

  const reactions = message.reactions as Record<string, number> | undefined

  const fileName = file.split("/").pop()

  return (

    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.2 }}
      className={`flex gap-3 ${isMe ? "justify-end" : ""}`}
      onMouseEnter={() => setShowBar(true)}
      onMouseLeave={() => setShowBar(false)}
    >

      {!isMe && !grouped && (
        <div className="h-8 w-8 rounded-full bg-gray-700 flex items-center justify-center text-xs text-white">
          {avatar}
        </div>
      )}

      <div>

        {!grouped && !isMe && (
          <div className="text-xs text-gray-400 mb-1">
            {message.username}
          </div>
        )}

        <div
          className={`rounded-lg px-3 py-2 max-w-xs break-words ${
            isMe
              ? "bg-blue-600 text-white"
              : "bg-gray-800 text-white"
          }`}
        >

          {editing ? (

            <input
              value={editText}
              autoFocus
              onChange={(e) => setEditText(e.target.value)}
              onKeyDown={(e) => {

                if (e.key === "Enter") {
                  if (message._id) {
                    editMessage(message._id, editText)
                  }
                  setEditing(false)
                }

                if (e.key === "Escape") {
                  setEditing(false)
                }

              }}
              className="bg-transparent text-white outline-none w-full"
            />

          ) : (

            <>
              {/* TEXT MESSAGE */}
              {message.type === "text" && (
                <div>{message.message}</div>
              )}

              {/* IMAGE */}
              {isImage && (
                <img
                  src={file}
                  className="rounded-md max-h-60"
                />
              )}

              {/* VIDEO */}
              {isVideo && (
                <video
                  src={file}
                  controls
                  className="rounded-md max-h-60"
                />
              )}

              {/* AUDIO */}
              {isAudio && (
                <audio
                  src={file}
                  controls
                />
              )}

              {/* DOCUMENT */}
              {isDoc && (
                <a
                  href={file}
                  target="_blank"
                  className="flex items-center gap-3 bg-gray-700 p-2 rounded-md hover:bg-gray-600"
                >
                  <span className="text-lg">📄</span>
                  <div className="flex flex-col text-sm">
                    <span>{fileName}</span>
                    <span className="text-xs text-gray-300">Download</span>
                  </div>
                </a>
              )}
            </>

          )}

        </div>

        <div className="text-xs text-gray-400 mt-1 flex gap-3 flex-wrap items-center">

          <span>{time}</span>

          {message.status && (
            <span>{message.status}</span>
          )}

          {reactions &&
            Object.entries(reactions).map(([emoji, count]) => (
              <span key={emoji}>
                {emoji} {count}
              </span>
            ))
          }

          {showBar && (
            <div className="flex gap-2">

              {["👍", "❤️", "😂", "🔥"].map((e) => (
                <button
                  key={e}
                  onClick={() => message._id && react(message._id, e)}
                  className="hover:scale-110 transition"
                >
                  {e}
                </button>
              ))}

              {isMe && (
                <>
                  <button
                    onClick={() => setEditing(true)}
                    className="text-blue-400"
                  >
                    edit
                  </button>

                  <button
                    onClick={() => message._id && deleteMessage(message._id)}
                    className="text-red-400"
                  >
                    delete
                  </button>
                </>
              )}

            </div>
          )}

        </div>

      </div>

    </motion.div>

  )

}