"use client"

import { useEffect, useRef, useState } from "react"
import { getSocket, ChatMessage, OnlineUser } from "../lib/socket"

import MessageList from "./MessageList"
import ChatInput from "./ChatInput"
import OnlineUsers from "./OnlineUsers"

type Props = {
  username: string
  room: string
}

export default function ChatView({ username, room }: Props) {

  const socketRef = useRef(getSocket())
  const bottomRef = useRef<HTMLDivElement | null>(null)

  const [messages, setMessages] = useState<ChatMessage[]>([])
  const [onlineUsers, setOnlineUsers] = useState<OnlineUser[]>([])
  const [typingUser, setTypingUser] = useState("")
  const [search, setSearch] = useState("")
  const [pinned, setPinned] = useState<ChatMessage[]>([])

  /* ---------- Scroll ---------- */

  const scrollToBottom = () => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" })
  }

  /* ---------- Socket Setup ---------- */

  useEffect(() => {

    const socket = socketRef.current

    if (!socket) return

    socket.emit("join-room", { name: username, room })

    /* ---------- Chat History ---------- */

    socket.on("chat-history", (history: ChatMessage[]) => {
      setMessages(history)
      scrollToBottom()
    })

    /* ---------- New Message ---------- */

    socket.on("receive", (msg: ChatMessage) => {

      setMessages(prev => {

        const exists = prev.find(m => m._id === msg._id)
        if (exists) return prev

        return [...prev, msg]

      })

      if (msg.pinned) {
        setPinned(prev => [...prev, msg])
      }

      scrollToBottom()

    })

    /* ---------- Online Users ---------- */

    socket.on("online-users", (users: OnlineUser[]) => {
      setOnlineUsers(users)
    })

    /* ---------- Typing Indicator ---------- */

    socket.on("typing", ({ username }) => {
      setTypingUser(username)
    })

    socket.on("stop-typing", () => {
      setTypingUser("")
    })

    /* ---------- Reactions ---------- */

    socket.on("message-reacted", ({ messageId, reactions }) => {

      setMessages(prev =>
        prev.map(m =>
          m._id === messageId
            ? { ...m, reactions }
            : m
        )
      )

    })

    /* ---------- Message Edited ---------- */

    socket.on("message-edited", ({ messageId, newText }) => {

      setMessages(prev =>
        prev.map(m =>
          m._id === messageId
            ? { ...m, message: newText, edited: true }
            : m
        )
      )

    })

    /* ---------- Message Deleted ---------- */

    socket.on("message-deleted", ({ messageId }) => {

      setMessages(prev =>
        prev.filter(m => m._id !== messageId)
      )

    })

    /* ---------- Message Delivered ---------- */

    socket.on("message-delivered", ({ messageId }) => {

      setMessages(prev =>
        prev.map(m =>
          m._id === messageId
            ? { ...m, status: "delivered" }
            : m
        )
      )

    })

    /* ---------- Message Seen ---------- */

    socket.on("message-seen", ({ messageId }) => {

      setMessages(prev =>
        prev.map(m =>
          m._id === messageId
            ? { ...m, status: "seen" }
            : m
        )
      )

    })

    /* ---------- Pinned Message ---------- */

    socket.on("message-pinned", ({ messageId, pinned }) => {

      setMessages(prev =>
        prev.map(m =>
          m._id === messageId
            ? { ...m, pinned }
            : m
        )
      )

    })

    /* ---------- Older Messages (Infinite Scroll) ---------- */

    socket.on("older-messages", (older: ChatMessage[]) => {

      setMessages(prev => [...older, ...prev])

    })

    /* ---------- Cleanup ---------- */

    return () => {

      socket.off("chat-history")
      socket.off("receive")
      socket.off("online-users")
      socket.off("typing")
      socket.off("stop-typing")
      socket.off("message-reacted")
      socket.off("message-edited")
      socket.off("message-deleted")
      socket.off("message-delivered")
      socket.off("message-seen")
      socket.off("message-pinned")
      socket.off("older-messages")

    }

  }, [username, room])

  /* ---------- Send Message ---------- */

  const sendMessage = (msg: string) => {

    if (!msg.trim()) return

    socketRef.current.emit("send", msg)

  }

  /* ---------- Send File ---------- */

  const sendFile = async (file: File) => {

    const form = new FormData()
    form.append("file", file)

    const res = await fetch("/upload", {
      method: "POST",
      body: form
    })

    const data = await res.json()

    socketRef.current.emit("send-file", {
      filePath: data.filePath
    })

  }

  /* ---------- React ---------- */

  const react = (id: string, emoji: string) => {

    socketRef.current.emit("react-message", {
      messageId: id,
      emoji
    })

  }

  /* ---------- Edit ---------- */

  const editMessage = (id: string, text: string) => {

    socketRef.current.emit("edit-message", {
      messageId: id,
      newText: text
    })

  }

  /* ---------- Delete ---------- */

  const deleteMessage = (id: string) => {

    socketRef.current.emit("delete-message", {
      messageId: id
    })

  }

  /* ---------- Search Filter ---------- */

  const filteredMessages = messages.filter(m =>
    m.message?.toLowerCase().includes(search.toLowerCase())
  )

  /* ---------- UI ---------- */

  return (

    <div className="flex h-full">

      <div className="flex flex-col flex-1">

        {/* ---------- Pinned Message ---------- */}

        {pinned.length > 0 && (
          <div className="bg-yellow-900 text-yellow-200 p-2 text-sm">
            📌 {pinned[pinned.length - 1].message}
          </div>
        )}

        {/* ---------- Search ---------- */}

        <div className="border-b border-gray-700 p-3 bg-gray-900">

          <input
            placeholder="Search messages..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="bg-gray-800 text-white p-2 text-sm rounded-md w-full"
          />

        </div>

        {/* ---------- Messages ---------- */}

        <MessageList
          messages={filteredMessages}
          currentUser={username}
          react={react}
          editMessage={editMessage}
          deleteMessage={deleteMessage}
        />

        {/* ---------- Typing Indicator ---------- */}

        {typingUser && (
          <div className="px-3 py-1 text-gray-400 text-xs">
            {typingUser} typing...
          </div>
        )}

        <div ref={bottomRef}></div>

        {/* ---------- Input ---------- */}

        <ChatInput
          sendMessage={sendMessage}
          sendFile={sendFile}
          typing={() => socketRef.current.emit("typing")}
          stopTyping={() => socketRef.current.emit("stop-typing")}
        />

      </div>

      {/* ---------- Online Users ---------- */}

      <OnlineUsers users={onlineUsers} />

    </div>

  )

}